public java.util.List<java.util.List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> result = new java.util.ArrayList<>();
    if (nums == null) {
        return result;
    }
    int n = nums.length;
    if (n == 0) {
        return result;
    }
    java.util.List<Integer> current = new java.util.ArrayList<>(n);
    boolean[] used = new boolean[n];
    dfs(nums, used, current, result);
    return result;
}

private void dfs(int[] nums, boolean[] used, java.util.List<Integer> current, java.util.List<java.util.List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new java.util.ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        dfs(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    // Handle null or empty input
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Build a set of all substrings for each string
    List<Set<String>> substringSets = new ArrayList<>();
    for (String s : strings) {
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }

    // Generate candidate substrings from the first string
    String first = strings.get(0);
    Set<String> candidates = new HashSet<>();
    int firstLen = first.length();
    for (int i = 0; i < firstLen; i++) {
        for (int j = i + 1; j <= firstLen; j++) {
            String sub = first.substring(i, j);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
    }

    int maxLen = 0;
    for (String candidate : candidates) {
        int candidateLen = candidate.length();
        if (candidateLen <= maxLen) {
            continue; // no need to check shorter candidates
        }
        String reverseCandidate = new StringBuilder(candidate).reverse().toString();
        boolean allContain = true;
        for (Set<String> set : substringSets) {
            if (!set.contains(candidate) && !set.contains(reverseCandidate)) {
                allContain = false;
                break;
            }
        }
        if (allContain) {
            maxLen = candidateLen;
        }
    }

    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    int deposits = 0;
    // Directions for 8-connectivity
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    // Use ArrayDeque as a stack for DFS
    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@') {
                deposits++;
                // Mark visited by turning '@' into '*'
                grid[r][c] = '*';
                stack.push(new int[]{r, c});
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0], cc = cell[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                            grid[nr][nc] = '*'; // mark visited
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }

    return deposits;
}

