public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }

        // Assume start[0] and end[0] represent node IDs
        if (start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }
        int startNode = start[0];
        int endNode = end[0];

        // Determine the maximum node index to size adjacency list
        int maxNode = Math.max(startNode, endNode);
        for (int[] p : paths) {
            if (p == null || p.length < 2) continue;
            maxNode = Math.max(maxNode, Math.max(p[0], p[1]));
        }

        // Build adjacency list
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= maxNode; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] p : paths) {
            if (p == null || p.length < 2) continue;
            int u = p[0];
            int v = p[1];
            if (u < 0 || v < 0 || u > maxNode || v > maxNode) continue;
            adj.get(u).add(v);
            adj.get(v).add(u); // assuming undirected paths
        }

        // BFS to check connectivity
        boolean[] visited = new boolean[maxNode + 1];
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(startNode);
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endNode) {
                return "can be travelled";
            }
            for (int nb : adj.get(cur)) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // In case of any runtime issue, default to cannot be travelled
        return "cannot be travelled";
    }
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words must not be null.");
    }
    word1 = word1.trim();
    word2 = word2.trim();
    if (word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Input words must not be empty.");
    }
    int lenSum = word1.length() + word2.length();
    // Count distinct letters present in both words
    java.util.Set<Character> set1 = new java.util.HashSet<>();
    for (char c : word1.toCharArray()) set1.add(c);
    java.util.Set<Character> set2 = new java.util.HashSet<>();
    for (char c : word2.toCharArray()) set2.add(c);
    set1.retainAll(set2);
    int commonDistinct = set1.size();
    int numerator = commonDistinct * 2; // each common letter counted twice
    if (numerator == 0) {
        return String.format("appx(%s, %s) = 0", word1, word2);
    }
    if (numerator == lenSum) {
        return String.format("appx(%s, %s) = 1", word1, word2);
    }
    int gcd = java.lang.Math.abs(gcd(numerator, lenSum));
    int reducedNum = numerator / gcd;
    int reducedDen = lenSum / gcd;
    return String.format("appx(%s, %s) = %d/%d", word1, word2, reducedNum, reducedDen);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

