public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    try {
        while (left <= right) {
            int mid = left + ((right - left) >> 1);
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[left] <= nums[mid]) { // left half is sorted
                if (nums[left] <= target && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else { // right half is sorted
                if (nums[mid] < target && target <= nums[right]) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }
    } catch (Exception e) {
        // In case of unexpected runtime issues, return -1
        return -1;
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = arr.length;
    if (n == 0) {
        throw new IllegalArgumentException("Input array cannot be empty.");
    }
    // Determine number of elements to remove from each end (5%).
    int trimCount = (int) Math.floor(n * 0.05);
    // Copy and sort the array to identify the smallest and largest 5%.
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    // Sum the remaining elements.
    long sum = 0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += sorted[i];
    }
    int remaining = n - 2 * trimCount;
    return (double) sum / remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    if (k <= 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) return false;
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) return false;
    for (int r = 1; r < k / 2; r++) {
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple length must equal n");
    }

    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length != 2) {
                throw new IllegalArgumentException("Each edge must contain exactly two nodes");
            }
            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Edge node out of bounds");
            }
            adj[u].add(v);
            adj[v].add(u);
        }
    } else {
        if (n > 1) {
            // Tree with multiple nodes but no edges: invalid input
            return 0;
        }
    }

    // Iterative DFS to process nodes in post-order
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    parent[0] = -2; // mark root visited
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : adj[node]) {
            if (parent[nei] == -1) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    int total = 0;
    int[] subtreeHas = new int[n];
    for (int i = idx - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei : adj[node]) {
            if (parent[nei] == node && subtreeHas[nei] == 1) {
                has = true;
                total += 2; // go to child and back
            }
        }
        subtreeHas[node] = has ? 1 : 0;
    }
    return total;
}

