public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int open = 0;       // number of unmatched '(' encountered so far
    int insertions = 0; // number of '(' needed before a ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else if (c == ')') {
            if (open > 0) {
                open--; // match with a previous '('
            } else {
                insertions++; // need an '(' before this ')'
            }
        } else {
            throw new IllegalArgumentException(
                "Invalid character at index " + i + ": " + c);
        }
    }
    // remaining unmatched '(' require ')'
    return insertions + open;
}

public int minOperations(int n) {
