public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) return 0;
    int maxEnding = nums[0];
    int maxSum = nums[0];
    int minEnding = nums[0];
    int minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSum = Math.max(maxSum, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSum = Math.min(minSum, minEnding);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        int f = fibs.get(i);
        if (k >= f) {
            k -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Validate inputs
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();

    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int pair = n / i;
            if (pair != i) {
                large.add(pair);
            }
        }
    }

    int smallCount = small.size();
    if (k <= smallCount) {
        return small.get(k - 1);
    }

    int remaining = k - smallCount;
    int largeCount = large.size();
    if (remaining > largeCount) {
        return -1;
    }

    // large list stores factors in decreasing order, so pick the (largeCount - remaining)-th element
    int index = largeCount - remaining;
    return large.get(index);
}

