public String getSmallestString(int n, int k) {
    if (n < 0 || k < 0) {
        return "";
    }
    // The minimum sum is n (all 'a's) and the maximum is 26*n (all 'z's)
    if (k < n || k > 26 * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // 'a' to 'z', max +25
        sb.setCharAt(i, (char) (sb.charAt(i) + add));
        remaining -= add;
    }
    return sb.toString();
}

