public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int bitCount = 0;
        int mask = 1 << bit;
        for (int num : nums) {
            if ((num & mask) != 0) {
                bitCount++;
            }
        }
        if (bitCount % 3 != 0) {
            result |= mask;
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    // Handle invalid range
    if (low > high) {
        return new ArrayList<>();
    }

    // Ensure low is at least 0 (stepping numbers are non-negative integers)
    if (low < 0) {
        low = 0;
    }

    TreeSet<Integer> resultSet = new TreeSet<>();

    // Explore starting digits from 0 to 9
    for (int startingDigit = 0; startingDigit <= 9; startingDigit++) {
        if (startingDigit > high) {
            break; // no need to process larger starting digits
        }

        Queue<Long> queue = new LinkedList<>();
        queue.offer((long) startingDigit);

        while (!queue.isEmpty()) {
            long current = queue.poll();

            if (current > high) {
                continue; // prune branches that exceed the upper bound
            }

            if (current >= low) {
                resultSet.add((int) current);
            }

            // Do not generate further numbers if current is 0 to avoid redundant paths like 0 -> 1 -> 0?
            // It's safe to continue; the algorithm will naturally avoid duplicates due to the set.
            long lastDigit = current % 10;

            // Extend the number by adding a new digit that is one less than the last digit
            if (lastDigit > 0) {
                long next = current * 10 + (lastDigit - 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }

            // Extend the number by adding a new digit that is one more than the last digit
            if (lastDigit < 9) {
                long next = current * 10 + (lastDigit + 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
        }
    }

    return new ArrayList<>(resultSet);
}

public static int countDigitOne(int n) {
    // Handle non-positive input
    if (n <= 0) {
        return 0;
    }
    int count = 0;
    long factor = 1;
    long nLong = n;
    while (nLong / factor > 0) {
        long lower = nLong % factor;
        long cur = (nLong / factor) % 10;
        long higher = nLong / (factor * 10);
        if (cur == 0) {
            count += higher * (int)factor;
        } else if (cur == 1) {
            count += higher * (int)factor + (int)lower + 1;
        } else {
            count += (higher + 1) * (int)factor;
        }
        factor *= 10;
    }
    return count;
}

