public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        int temp = num;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    try {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                    vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                    diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                    anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                    int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                            Math.max(diag[i][j], anti[i][j]));
                    if (localMax > max) {
                        max = localMax;
                    }
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issues (e.g., irregular matrix shape), return 0
        return 0;
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero straight away
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    // Work with absolute value to simplify processing
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (value > 0) {
        sb.append(value % 10);
        value /= 10;
        digitCount++;
        if (value > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    // If negative, add minus sign
    if (negative) {
        sb.append('-');
    }
    // The string is built in reverse order, reverse it to correct
    return sb.reverse().toString();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    int maxArea = 0;
    int i = 0;
    int n = heights.length;
    while (i < n) {
        if (stack.isEmpty() || heights[i] >= heights[stack.peek()]) {
            stack.push(i);
            i++;
        } else {
            int topIndex = stack.pop();
            int height = heights[topIndex];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = (int) area;
            }
        }
    }
    while (!stack.isEmpty()) {
        int topIndex = stack.pop();
        int height = heights[topIndex];
        int width = stack.isEmpty() ? i : i - stack.peek() - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = (int) area;
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Verify matrix is rectangular
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must have the same length");
        }
    }
    int[] result = new int[m * n];
    int i = 0, j = 0;
    boolean up = true;
    for (int k = 0; k < result.length; k++) {
        result[k] = mat[i][j];
        if (up) {
            if (j == n - 1) {
                i++;
                up = false;
            } else if (i == 0) {
                j++;
                up = false;
            } else {
                i--;
                j++;
            }
        } else { // moving downwards
            if (i == m - 1) {
                j++;
                up = true;
            } else if (j == 0) {
                i++;
                up = true;
            } else {
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] charDigits = Integer.toString(n).toCharArray();
    int len = charDigits.length;
    int[] digits = new int[len];
    for (int i = 0; i < len; i++) {
        digits[i] = charDigits[i] - '0';
    }

    // Find the longest non-increasing suffix
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) { // digits are in descending order => no greater permutation
        return -1;
    }

    // Find the rightmost successor to pivot in the suffix
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the pivot with its successor
    int tmp = digits[i];
    digits[i] = digits[j];
    digits[j] = tmp;

    // Reverse the suffix
    int left = i + 1, right = len - 1;
    while (left < right) {
        tmp = digits[left];
        digits[left] = digits[right];
        digits[right] = tmp;
        left++;
        right--;
    }

    // Construct the result and check bounds
    long result = 0;
    for (int d : digits) {
        result = result * 10 + d;
        if (result > Integer.MAX_VALUE) {
            return -1; // would overflow int
        }
    }
    if (result <= n) {
        return -1; // should always be larger, but safeguard
    }
    return (int) result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }
    try {
        char[] arr = new char[n];
        backtrack(result, arr, 0, n - 1);
    } catch (Exception e) {
        // Return what has been collected so far in case of error
    }
    java.util.Collections.sort(result);
    return result;
}

private static void backtrack(java.util.List<String> res, char[] arr, int left, int right) {
    if (left > right) {
        res.add(new String(arr));
        return;
    }
    if (left == right) {
        char[] middle = {'0', '1', '8'};
        for (char c : middle) {
            arr[left] = c;
            res.add(new String(arr));
        }
        return;
    }
    char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'6', '9'},
        {'8', '8'},
        {'9', '6'}
    };
    for (char[] p : pairs) {
        if (left == 0 && p[0] == '0') {
            continue; // leading zero is not allowed
        }
        arr[left] = p[0];
        arr[right] = p[1];
        backtrack(res, arr, left + 1, right - 1);
    }
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length < 2) {
                return false;
            }
        }
        // Check for distinct points
        if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
            (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
            (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
            return false;
        }
        long x1 = points[0][0], y1 = points[0][1];
        long x2 = points[1][0], y2 = points[1][1];
        long x3 = points[2][0], y3 = points[2][1];
        long cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
        return cross != 0;
    } catch (Exception e) {
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

